PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS `sources`(
    `id` INTEGER NOT NULL PRIMARY KEY,
    `url` TEXT NOT NULL,
    `last_checked` TEXT NOT NULL
, enabled INTEGER NOT NULL DEFAULT 1, failed_count INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS `activities`(
                `id` INTEGER NOT NULL PRIMARY KEY,
                `source_id` INTEGER NOT NULL,
                `post_url` TEXT NOT NULL,
                `timestamp` TEXT NOT NULL
            );
CREATE TABLE IF NOT EXISTS `logins`(
                `id` INTEGER NOT NULL PRIMARY KEY,
                `timestamp` TEXT NOT NULL,
                `key` TEXT NOT NULL UNIQUE
            );
CREATE TABLE IF NOT EXISTS `roadmap_activities` (`id` INTEGER NOT NULL PRIMARY KEY, `timestamp` TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS `roadmap_watched_tabs` (`id` INTEGER NOT NULL PRIMARY KEY, `tab_roadmap_id` TEXT NOT NULL UNIQUE, `timestamp` TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS `roadmap_cards` (`id` INTEGER NOT NULL PRIMARY KEY, `roadmap_id` TEXT NOT NULL, `name` TEXT NOT NULL, `description` TEXT NOT NULL, `image_url` TEXT, `slug` TEXT NOT NULL, `timestamp` TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS `roadmap_tabs` (`id` INTEGER NOT NULL PRIMARY KEY, `roadmap_id` TEXT NOT NULL UNIQUE, `name` TEXT NOT NULL, `slug` TEXT NOT NULL, `timestamp` TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS `roadmap_card_assignments` (`id` INTEGER NOT NULL PRIMARY KEY, `activity_id` INTEGER NOT NULL, `tab_id` INTEGER NOT NULL, `card_id` INTEGER NOT NULL, `section_position` INTEGER NOT NULL, `card_position` INTEGER NOT NULL, `timestamp` TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS `roadmap_tab_assignments` (`id` INTEGER NOT NULL PRIMARY KEY, `activity_id` INTEGER NOT NULL, `tab_id` INTEGER NOT NULL, `timestamp` TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS `roadmap_changes` (`id` INTEGER NOT NULL PRIMARY KEY, `type` TEXT NOT NULL, `activity_id` INTEGER NOT NULL, `previous_card_id` INTEGER, `current_card_id` INTEGER, `tab_id` INTEGER, `timestamp` TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS `db_version` (`id` INTEGER NOT NULL PRIMARY KEY, `version_number` INTEGER NOT NULL);
CREATE INDEX idx_key ON logins (KEY);
COMMIT;
